import { createWorkflowChain, andAgent, andAll } from '@voltagent/core';
import { openai } from '@ai-sdk/openai';

// Create the parallel workflow
export const parallelWorkflow = createWorkflowChain({
  name: 'parallel-analysis-workflow',
  input: {
    type: 'string',
    description: 'Input text to analyze in parallel'
  },
  steps: [
    {
      id: 'parallel-analysis',
      type: 'andAll',
      steps: [
        // First parallel agent: Sentiment analysis
        andAgent({
          id: 'sentiment-analysis',
          name: 'Sentiment Analyzer',
          description: 'Analyze the sentiment of the input text',
          model: openai('gpt-4o-mini'),
          systemPrompt: 'You are a sentiment analysis expert. Analyze the sentiment of the given text and classify it as positive, negative, or neutral. Provide a brief explanation.',
          input: {
            type: 'string',
            description: 'Text to analyze for sentiment'
          },
          output: {
            type: 'object',
            properties: {
              sentiment: { type: 'string' },
              explanation: { type: 'string' }
            }
          }
        }),
        // Second parallel agent: Topic classification
        andAgent({
          id: 'topic-classification',
          name: 'Topic Classifier',
          description: 'Classify the topic of the input text',
          model: openai('gpt-4o-mini'),
          systemPrompt: 'You are a topic classification expert. Identify the main topic of the given text and classify it into a category. Provide relevant keywords.',
          input: {
            type: 'string',
            description: 'Text to classify by topic'
          },
          output: {
            type: 'object',
            properties: {
              topic: { type: 'string' },
              category: { type: 'string' },
              keywords: { type: 'array', items: { type: 'string' } }
            }
          }
        }),
        // Third parallel agent: Summary generation
        andAgent({
          id: 'summary-generation',
          name: 'Summary Generator',
          description: 'Generate a concise summary of the input text',
          model: openai('gpt-4o-mini'),
          systemPrompt: 'You are a skilled summarizer. Create a concise summary of the given text in 2-3 sentences, capturing the main points.',
          input: {
            type: 'string',
            description: 'Text to summarize'
          },
          output: {
            type: 'object',
            properties: {
              summary: { type: 'string' },
              wordCount: { type: 'number' }
            }
          }
        })
      ]
    }
  ]
});

